581	  .panel-pad{--panel-pad-y:clamp(28px,4.6vw,52px);}
582	
583	  /* Alla kickers som INTE är monoregister. Monobudgeten är fyra etiketter på
584	     hela sidan och de är: kortbaksidans kicker, kortbaksidans tjänsterad,
585	     Exempelsida-kickern i tesen, och liggarens siffror. Allt annat som ser ut
586	     som en etikett sätts i Public Sans 600. */
587	  .kicker-sans{font-family:var(--font);font-weight:600;font-size:11px;
588	    letter-spacing:.16em;text-transform:uppercase;}
589	
590	  /* ---------------------------------------------------------- tesbandet
591	     PLAN 054 steg 1. En pinnad akt, sidans enda mättade färgblock, och
592	     accentens FÖRSTA av två förekomster. INTE en ruta på 45% vw bredvid en
593	     jätte: stagen äger 100% vw x 100% vh, en mening i taget i rubrikplatsen
594	     (--i via style="--i:N" per <h2>/<p class="ts">, N/5 av --sc-ps var). */
595	  .thesis{position:relative;z-index:2;--n:4;}
596	  /* Astra r7 material_fixes #6: .62fr gav bildkolumnen 496px = 34,4%vw
597	     vid 1440 (mål >=36%/519px). .7fr: 0,7/1,7 av den tillgängliga
598	     bredden = 534px = 37,1%vw - samma vw-andel vid 768 (rail-x och
599	     column-gap är båda vw-baserade, förhållandet skalar). */
600	  .thesis-stage{background:var(--c-accent);color:var(--c-white);
601	    display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.7fr);
602	    grid-template-rows:minmax(0,1fr) auto;column-gap:clamp(24px,4vw,64px);
603	    padding:clamp(72px,12svh,120px) 0 clamp(28px,5svh,48px) var(--rail-x);
604	    border-bottom:1px solid var(--frame-line);overflow:clip;}
605	  .thesis-lines{grid-column:1;grid-row:1;align-self:center;display:grid;min-width:0;}
606	  .ts{grid-area:1/1;align-self:start;min-width:0;
607	    font-family:var(--f-display);font-weight:700;
608	    font-size:clamp(2rem,5vw + 1rem,6rem);line-height:.98;letter-spacing:-.02em;
609	    text-transform:uppercase;text-wrap:balance;overflow-wrap:normal;hyphens:manual;}
610	  /* Bytet: rubrikradens överkant och underkant är en springa. Utgående
611	     mening stiger ut genom överkanten, inkommande stiger upp ur
612	     underkanten. --in/--out läser --sc-ps (F-014), linjärt över --f.
613	     Astra r7 material_fixes #1: symmetriska ±f/2-fönster kring samma
614	     punkt b (mening N:s eget slut = mening N+1:s eget start) lät båda
615	     transformeras SAMTIDIGT över samma spann - två meningar delvis
616	     synliga på en gång, uppmätt 130px överlapp vid 1440. Asymmetriskt
617	     i stället: --in öppnar över [a, a+f] (från sin EGEN start), --out
618	     stänger över [b-f, b] (till sin EGEN slutpunkt). Vid b är utgående
619	     redan helt stängd (--out=1) precis när inkommande fortfarande
620	     står på 0 (--in=0, ej påbörjad) - en ren växling, 0px överlapp,
621	     0px lucka. */
622	  /* PLAN 057 1.1: letter-spacing var förut --in-driven (upp till +.06em vid
623	     --in=0), låst till -.02em bara under 768 sedan R10 (mobilhoppet). Med
624	     en spalt tätt dimensionerad mot bredaste ordet (14cqi, se @media
625	     min-width:1024px nedan) får ordet ALDRIG bli 0,66em bredare mitt i
626	     bytet - samma mekanism som R10:s 35px-hopp, fast på alla bredder.
627	     Låst på -.02em överallt; bytet bärs av clip-path/translate. */
628	  .js .ts{--a:calc(var(--i) / var(--n));--b:calc((var(--i) + 1) / var(--n));--f:.04;
629	    --in:clamp(0,calc((var(--sc-ps,0) - var(--a)) / var(--f)),1);
630	    --out:clamp(0,calc((var(--sc-ps,0) - (var(--b) - var(--f))) / var(--f)),1);
631	    clip-path:inset(calc(var(--out) * 100%) 0 calc((1 - var(--in)) * 100%) 0);
632	    transform:translateY(calc((1 - var(--in)) * .55em - var(--out) * .55em));
633	    letter-spacing:-.02em;}
634	  .js .ts:first-child{--in:1;}
635	  .js .ts:last-child{--out:0;}
636	  /* Lager 3: fyra streck (PLAN 057 6), det aktiva i fullt papper. Inga siffror (PRODUCT.md). */
637	  .thesis-ticks{grid-column:1;grid-row:2;display:flex;gap:10px;margin-top:clamp(20px,3svh,32px);}
638	  .thesis-ticks i{width:32px;height:2px;background:color-mix(in srgb,var(--c-white) 38%,var(--c-accent));}
639	  .js .thesis-ticks i{--on:clamp(0,calc(1 - abs((var(--sc-ps,0) - (var(--i) + .5) / var(--n)) * (2 * var(--n))) + 1),1);
640	    background:color-mix(in srgb,var(--c-white) calc(38% + 62% * var(--on)),var(--c-accent));}
641	  .thesis-figure{grid-column:2;grid-row:1 / span 2;align-self:end;min-width:0;margin:0;}
642	  .thesis-photo-box{position:relative;aspect-ratio:16/10;overflow:clip;
643	    border:1px solid var(--frame-line);border-right:0;}
644	  /* Lager 2: färgen kommer med mening 3 ("layout och bild"), --n:4 -> i=2,
645	     fönstret [.5,.75] (var det [.4,.6] vid fem meningar). */
646	  .thesis-photo-box img{width:100%;height:100%;object-fit:cover;
647	    filter:grayscale(calc(1 - clamp(0,calc((var(--sc-ps,0) - .5) / .2),1))) contrast(1.05);
648	    transform:scale(calc(1 + .06 * var(--sc-ps,0)));transform-origin:70% 40%;}
649	  .thesis-caption{margin-top:12px;padding-right:var(--rail-x);}
650	  .thesis-caption .cap-line{font-family:var(--f-mono);font-weight:400;
651	    font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;
652	    color:rgba(255,255,255,.92);}
653	  @media (max-width:767px){
654	    /* Astra r7 material_fixes #7: min-height reserverade 7 radhöjder
655	       (243px), men ingen mening tar mer än 4 (mening 3, längst, 60
656	       tecken) - ett ~104px tomt blått band stod kvar mellan meningen
657	       och strecken. 7->4. Tredje raden (bilden) satt till 1fr i stället
658	       för auto: det frigjorda utrymmet går dit i stället för att bli
659	       dött utrymme längst ned i stagen. */
660	    .thesis-stage{grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto 1fr;
661	      padding:clamp(56px,9svh,80px) var(--rail-x) clamp(20px,3svh,32px);row-gap:16px;}
662	    .thesis-lines{align-self:start;min-height:calc(4 * .98 * clamp(2rem,5vw + 1rem,6rem));}
663	    /* Astra r8 material_fixes #2: bas-regelns align-self:end (rad ~628)
664	       återställdes aldrig här - figuren tog bara sin EGEN innehållshöjd
665	       i stället för att fylla grid-radens 1fr, så flex:1 nedan hade
666	       inget fritt utrymme att växa in i och föll tillbaka på
667	       aspect-ratio:16/10 (bas-regeln, rad ~629, också aldrig
668	       återställd) = en kort bild med ett 285px tomt band ovanför. */
669	    .thesis-figure{grid-column:1;grid-row:3;min-height:0;display:flex;flex-direction:column;align-self:stretch;}
670	    /* flex:1 i stället för aspect-ratio-styrd höjd: boxen växer för att
671	       fylla den frigjorda raden. object-fit:cover (redan satt på img,
672	       rad ~619) beskär utan att distordera - ingen av dessa regler
673	       läser --sc-ps, så bilden flyttar sig aldrig mellan meningarna. */
674	    .thesis-photo-box{border-right:1px solid var(--frame-line);flex:1;min-height:0;aspect-ratio:auto;}
675	    /* R10 (lead-r9 fynd): boxen (portrait vid 320-767, t.ex. 343x448 vid
676	       390) är mycket smalare än bildens 16:10-källa (1200x750) - cover
677	       kröp tidigare kring center (standard 50% 50%) och skar bort både
678	       vänster- och högerkanten, "Systems" blev "ystems". Vänsterankrad
679	       beskärning visar rubriken hel. Bara i detta fönster: vid 768 matchar
680	       boxens 16:10-form redan källans, ingen beskärning sker där oavsett
681	       ankare; vid 1440 rörs varken regel eller rendering. */
682	    .thesis-photo-box img{object-position:left top;}
683	    .thesis-caption{padding-right:0;}
684	    /* Astra r10 material_fixes #1 (mobilhoppet) är nu överflödig som egen
685	       regel: PLAN 057 1.1 låste letter-spacing till -.02em på ALLA
686	       bredder (rad ~620), inte bara under 768 - samma fix, bredare. */
687	  }
688	  /* PLAN 057 1. Hyperborea som jämbördig huvudperson (hoy-home-1440--s01):
689	     bilden 1,2fr = 45,8% vw, fri från kanten med --rail-x på båda sidor,
690	     överkant i linje med meningens överkant. INTE en plåt lågt i hörnet
691	     som bleeder ut. Meningen begränsas av spalten (14cqi): bredaste ordet
692	     ARGUMENTET. är 6,82em, 14cqi ger >= 4% marginal. */
693	  @media (min-width:1024px){
694	    .thesis-stage{grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);
695	      padding:clamp(96px,16svh,168px) var(--rail-x) clamp(28px,5svh,48px);}
696	    .thesis-lines{align-self:start;container-type:inline-size;}
697	    .ts{font-size:min(clamp(2rem,5vw + 1rem,6rem),14cqi);}
698	    .thesis-figure{grid-row:1;align-self:start;}
699	    .thesis-photo-box{border-right:1px solid var(--frame-line);}
700	    .thesis-caption{padding-right:0;}
701	    .thesis-ticks{align-self:end;}
702	  }
703	  .no-js .ts,.no-js .cs{grid-area:auto;}
704	
705	  /* ---------------------------------------------------------- s5, Calyx
706	     Ljus iframe. flex:1 så att vänsterspalten möter högerspaltens avslut.
707	     Ramen transformeras eller tonas ALDRIG efter att den visats: den ska gå
708	     att använda. Reveal sker på wrappern, inte på ramen. */
709	  /* Ram och bildtext är EN figur, inte två syskon i spalten: en fristående

