   'pris-bro' visar nu #pris självt, med liggarens hårlinjer (plan 033,
   tröskel 0,18-0,36) fullt indragna - väntar in --sc-ps >= 0,4. */
if (mode === 'pris-bro'){
  var broEl = document.getElementById('pris');
  if (broEl){
    broEl.scrollIntoView({ block:'start' });
    var broTries = 0;
    (function waitBro(){
      var ps = parseFloat(getComputedStyle(broEl).getPropertyValue('--sc-ps'));
      broTries++;
      if (broTries < 40 && (isNaN(ps) || ps < 0.4)) requestAnimationFrame(waitBro);
    })();
  }
}

