    for w,h in widths:
        pg = b.new_page(viewport={"width":w,"height":h})
        pg.goto(URL)
        pg.wait_for_timeout(600)
        # scroll to very end
        pg.evaluate("window.scrollTo(0, document.documentElement.scrollHeight)")
