from playwright.sync_api import sync_playwright
from PIL import Image
import io
import sys

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
if len(sys.argv) > 1 and sys.argv[1] == "control":
    URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/_control/index_broken.html"

CONFIGS = [
    # width, height, dpr(zoom), preview mode, case selector
    (320, 900, 1.0, "case-calyx-01", "calyx"),
    (390, 900, 1.0, "case-calyx-01", "calyx"),
    (768, 900, 1.0, "case-calyx-01", "calyx"),
    (1024, 900, 1.0, "case-calyx-01", "calyx"),
    (1280, 900, 1.0, "case-calyx-01", "calyx"),
    (1440, 900, 1.0, "case-calyx-01", "calyx"),
    (1920, 930, 1.0, "case-calyx-01", "calyx"),
    (320, 900, 1.0, "case-horai-01", "horai"),
    (1920, 930, 1.0, "case-horai-01", "horai"),
    # DPR / zoom configs from device table
    (1536, 744, 1.25, "case-calyx-01", "calyx"),
    (1745, 845, 1.1, "case-calyx-01", "calyx"),
    (1280, 620, 1.5, "case-calyx-01", "calyx"),
    (2133, 1033, 0.9, "case-calyx-01", "calyx"),
    (1097, 531, 1.75, "case-calyx-01", "calyx"),
    (960, 465, 2.0, "case-calyx-01", "calyx"),
]

def is_magenta(px):
    r,g,b = px[0],px[1],px[2]
    return r > 235 and g < 20 and b > 235

def classify(img, x0, y0, x1, y1, label):
    w, h = img.size
    px = img.load()
    fails = 0
    total = 0
    # sample along each of the 4 edges, 30 points per edge (interior 1px, exterior 1px)
    def check_line(points, inward):
        nonlocal fails, total
        for (x, y) in points:
            xi = int(x); yi = int(y)
            if xi < 0 or yi < 0 or xi >= w or yi >= h: continue
            total += 1
            c = px[xi, yi]
            if not is_magenta(c):
                fails += 1
    # top edge, 1px inside
    xs = [x0 + (x1-x0)*i/29 for i in range(30)]
    check_line([(x, y0+1) for x in xs], None)
    check_line([(x, y1-1) for x in xs], None)
    ys = [y0 + (y1-y0)*i/29 for i in range(30)]
    check_line([(x0+1, y) for y in ys], None)
    check_line([(x1-1, y) for y in ys], None)
    return fails, total

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    for w, h, dpr, mode, case in CONFIGS:
        pg = b.new_page(viewport={"width": w, "height": h}, device_scale_factor=dpr)
        pg.goto(URL + "?preview=" + mode)
        sel = f"#case-{case} iframe"
        caseSel = f"#case-{case}"
        try:
            pg.wait_for_function(
                """(args) => {
                  const [csel, s] = args;
                  const el = document.querySelector(csel);
                  const ps = el ? parseFloat(getComputedStyle(el).getPropertyValue('--sc-ps')) : NaN;
                  const f = document.querySelector(s);
                  return !isNaN(ps) && ps > 0.01 && f && f.contentWindow && f.contentWindow.scrollY >= 0;
                }""",
                [caseSel, sel], timeout=15000)
        except Exception as e:
            print("wait failed", e)
        pg.wait_for_timeout(900)
        # inject magenta into iframe doc
        pg.evaluate("""(s) => {
          const f = document.querySelector(s);
          const d = f.contentDocument;
          const style = d.createElement('style');
          style.textContent = 'html,body{background:#ff00ff!important}body *{visibility:hidden!important}';
          d.head.appendChild(style);
        }""", sel)
        pg.wait_for_timeout(300)
        rect = pg.evaluate("""(s) => {
          const f = document.querySelector(s);
          const wrap = f.closest('.case-wrap');
          const r = wrap.getBoundingClientRect();
          return {x0:r.left, y0:r.top, x1:r.right, y1:r.bottom};
        }""", sel)
        shot = pg.screenshot()
        img = Image.open(io.BytesIO(shot))
        # screenshot pixels are device px; rect is CSS px -> scale by dpr
        sx0, sy0, sx1, sy1 = rect['x0']*dpr, rect['y0']*dpr, rect['x1']*dpr, rect['y1']*dpr
        fails, total = classify(img, sx0, sy0, sx1, sy1, f"{w}x{h}@{dpr}")
        print(f"{w}x{h}@{dpr} {mode}: fails={fails}/{total} rect={rect} img={img.size}")
        pg.close()
    b.close()

