from playwright.sync_api import sync_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
widths = [320,375,390,414,768,1024,1280,1440,1920]

check_js = """(sel) => {
  const els = Array.from(document.querySelectorAll(sel));
  const results = [];
  for (const el of els) {
    const text = el.textContent.trim();
    const words = text.split(/\\s+/).filter(Boolean);
    let splitCount = 0;
    for (const w of words) {
      if (w.length < 2) continue;
      const idx = text.indexOf(w);
      if (idx < 0) continue;
      const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
      let node, pos = 0, target=null, targetOffset=0;
      while (node = walker.nextNode()) {
        const len = node.textContent.length;
        if (idx >= pos && idx < pos+len) { target = node; targetOffset = idx-pos; break; }
        pos += len;
      }
      if (!target) continue;
      const range = document.createRange();
      try {
        range.setStart(target, targetOffset);
        range.setEnd(target, targetOffset + w.length);
        if (range.getClientRects().length > 1) splitCount++;
      } catch(e) {}
    }
    if (splitCount>0) results.push({cls: el.className, split: splitCount});
  }
  return results;
}"""

with sync_playwright() as p:
    b = p.chromium.launch()
    total_split = 0
    total_overflow = 0
    for w in widths:
        pg = b.new_page(viewport={"width":w, "height":900})
        pg.goto(URL)
        pg.wait_for_timeout(500)
        r = pg.evaluate("({scrollW: document.documentElement.scrollWidth, clientW: document.documentElement.clientWidth})")
        overflow = r["scrollW"] > r["clientW"]
        if overflow: total_overflow += 1
        split = 0
        for sel in [".case-name", ".case-line", ".ts", ".statement", ".price-ingress", ".cases-title", ".cases-lead", ".process-title", ".process-step-title"]:
            res = pg.evaluate(check_js, sel)
            split += sum(x["split"] for x in res)
            if res:
                print(w, sel, res)
        total_split += split
        print(w, r, "OVERFLOW" if overflow else "ok", "split=", split)
        pg.close()
    print("TOTAL overflow widths:", total_overflow, "TOTAL split words:", total_split)
    b.close()

