        xs = [sx0 + (sx1-sx0)*i/29 for i in range(30)]
        ys = [sy0 + (sy1-sy0)*i/29 for i in range(30)]
        def report(points, label):
            for (x,y) in points:
                xi, yi = int(x), int(y)
                if xi<0 or yi<0 or xi>=img.size[0] or yi>=img.size[1]: continue
                c = px[xi,yi]
                if not is_magenta(c):
                    print(f"  {label} FAIL at dev({xi},{yi}) color={c}")
        report([(x, sy0+1) for x in xs], "top")
        report([(x, sy1-1) for x in xs], "bottom")
        report([(sx0+1, y) for y in ys], "left")
        report([(sx1-1, y) for y in ys], "right")
        pg.close()
    b.close()

