    pg = b.new_page(viewport={"width": 1280, "height": 620}, device_scale_factor=1.5)
    pg.goto(URL + "?preview=case-calyx-01")
    pg.wait_for_function(
        """() => {
          const el = document.getElementById('case-calyx');
          const ps = el ? parseFloat(getComputedStyle(el).getPropertyValue('--sc-ps')) : NaN;
          const f = document.querySelector('#case-calyx iframe');
          return !isNaN(ps) && ps > 0.01 && f && f.contentWindow && f.contentWindow.scrollY >= 0;
        }""", timeout=15000)
    pg.wait_for_timeout(1000)
    pg.evaluate("""() => {
      const f = document.querySelector('#case-calyx iframe');
      const d = f.contentDocument;
      const style = d.createElement('style');
      style.textContent = 'html,body{background:#ff00ff!important}body *{visibility:hidden!important}';
      d.head.appendChild(style);
    }""")
    pg.wait_for_timeout(700)
    rect = pg.evaluate("""() => {
      const f = document.querySelector('#case-calyx iframe');
      const wrap = f.closest('.case-wrap');
      const r = wrap.getBoundingClientRect();
      const fr = f.getBoundingClientRect();
      return {wrap:r, iframe:fr};
    }""")
    shot = pg.screenshot()
    img = Image.open(io.BytesIO(shot))
    px = img.load()
    dpr = 1.5
    xcheck = int(700 * dpr)  # a fixed x within the frame, device px
    print("wrap", rect['wrap'])
    print("iframe", rect['iframe'])
    print("wrap.bottom device:", rect['wrap']['bottom']*dpr)
    print("iframe.bottom device:", rect['iframe']['bottom']*dpr)
    for y in range(885, 915):
        c = px[xcheck, y]
        print(y, c)
    b.close()

